{
  "id": 32,
  "knowledge": "Failing Operation",
  "description": "An operation characterized by poor logistical performance and low effectiveness.",
  "definition": "An operation is 'Failing' if its Logistical Throughput per Vehicle (LTV) is below 1.0 OR its Response Effectiveness Score (RES) is below 40."
}

{
  "id": 28,
  "knowledge": "Highly Effective Operation",
  "description": "An operation that demonstrates excellence across coordination, logistics, and beneficiary satisfaction.",
  "definition": "An operation is 'Highly Effective' if its Response Effectiveness Score (RES) is greater than 75 AND its Coordination Quality Index (CQI) is greater than 75."
}

{
  "id": 34,
  "knowledge": "Successful Community Partnership",
  "description": "Identifies operations with excellent community relations and equitable aid distribution.",
  "definition": "A 'Successful Community Partnership' exists when community engagement is 'High' and the distribution equity index is greater than 0.9."
}

{
  "id": 14,
  "knowledge": "Response Effectiveness Score (RES)",
  "description": "A composite score measuring the overall effectiveness of the response operation.",
  "definition": "A weighted score of an operation's success. Formula: (0.4 * success_rate) + (0.3 * bene_feedbackscore * 10) + (0.3 * distequityidx * 100)."
}

{
  "id": 15,
  "knowledge": "Coordination Quality Index (CQI)",
  "description": "An index measuring the quality of inter-agency coordination and information management.",
  "definition": "A composite score assessing collaboration effectiveness. Formula: (report_compliance + (stakeholder_satisf * 20) + (dataqualityvalue * 20)) / 3.0."
}

{
  "id": 47,
  "knowledge": "Funding States",
  "description": "Describes the financial health of an operation in relation to its needs.",
  "definition": "'Adequate': Sufficient funds are available. 'Limited': Funding is available but does not cover all needs, requiring prioritization. 'Critical': A severe funding gap threatens essential activities."
}

{
  "id": 43,
  "knowledge": "Response Phases",
  "description": "The distinct phases of a disaster management cycle, from immediate action to long-term rebuilding.",
  "definition": "'Initial': First 24-72 hours, focus on life-saving. 'Emergency': Period of active, large-scale relief. 'Recovery': Transition to restoring services. 'Reconstruction': Long-term rebuilding of infrastructure and society."
}
